def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # A color is part of the drawing if it has a connected component
    # large enough to be a genuine shape.
    seen = [[False] * w for _ in range(h)]
    shape_colors = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and not seen[yy][xx]
                            and grid[yy][xx] == color):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if size >= 4:
                shape_colors.add(color)

    out = [row[:] for row in grid]
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in shape_colors:
                continue

            neighbors = {}
            for dy, dx in directions:
                y, x = r + dy, c + dx
                if 0 <= y < h and 0 <= x < w and grid[y][x] in shape_colors:
                    neighbors.setdefault(grid[y][x], []).append((dy, dx))

            replacement = bg
            for candidate, dirs in neighbors.items():
                # Repair a marker embedded in a shape, but don't bridge
                # two otherwise separate regions with a lone marker.
                if len(dirs) >= 2 and any(
                    d1[0] * d2[0] + d1[1] * d2[1] == 0
                    for i, d1 in enumerate(dirs)
                    for d2 in dirs[i + 1:]
                ):
                    replacement = candidate
                    break
            out[r][c] = replacement

    return out
